$string['importdossierarchive'] = 'Archive (fichier zip produit par l\'export)';
$string['importdossierdone'] = 'Dossier reconstruit : {$a->declarations} déclaration(s), {$a->attestations} attestation(s), {$a->rubriques} rubrique(s) du dossier de faisabilité restaurée(s), {$a->rubriquesgardees} laissée(s) telle(s) quelle(s) ; {$a->validation} rubrique(s) de la préparation du dossier de validation restaurée(s), {$a->validationgardees} laissée(s) telle(s) quelle(s) ; {$a->reflexion} entrée(s) du journal restaurée(s), {$a->reflexiongardees} laissée(s) telle(s) quelle(s) ; {$a->pieces} pièce(s) justificative(s) restaurée(s), {$a->piecesleft} non restaurée(s) (l\'archive ne porte ni fichier ni adresse pour elles, comme l\'export d\'un tiers, ou la jonction de pièces est fermée ici et elles sont seulement listées) ; {$a->horsactivite} compétence(s) dite(s) hors de l\'activité restaurée(s), {$a->horsactivitelaissees} laissée(s) telle(s) quelle(s) ou non tenue(s) ici.';
$string['importdossierforeign'] = 'Cette archive n\'a pas été délivrée par cette plateforme, ou son identifiant a été modifié : son authenticité ne peut pas être vérifiée ici. Ses empreintes montrent seulement que ses fichiers correspondent à son propre manifeste. Pour la faire confirmer, interrogez la plateforme qui l\'a délivrée sur l\'archive {$a}.';
$string['importdossierintro'] = 'Reconstruire ce dossier à partir d\'une archive exportée de ce site ou d\'un autre. Chaque fichier est vérifié contre son empreinte SHA-256 et chaque déclaration contre le schéma avant toute écriture ; la moindre anomalie fait refuser l\'archive entière. Les fiches de certification auxquelles renvoient les déclarations doivent avoir été importées d\'abord. L\'archive d\'un autre site n\'est reprise que si ce site n\'a pas déjà numéroté autrement les compétences qu\'elle nomme, ce qui arrive par exemple dès qu\'un dossier a quitté ce site sur ces compétences (archive, copie Word ou OpenDocument, sauvegarde), et si le compte du vaeiste n\'a pas déjà d\'identifiant sur ce site (il le reçoit dès sa première déclaration, son premier export, sa première copie ou sa première sauvegarde) ; sinon elle est refusée en entier, le message dit pourquoi, et rien n\'est importé. Une archive ne porte jamais les dépôts du dossier de faisabilité, les avis des responsables ni les questions de précision : ils ne reviennent pas.';
$string['importdossierpositioning'] = 'Positionnements de la structure : {$a->positionnement} ligne(s) restaurée(s), {$a->positionnementlaissees} laissée(s) telle(s) quelle(s) (une clé qui porte déjà une ligne ici, une fiche ou un rang que ce site ne tient pas, ou une ligne déjà présente). Ce sont des positionnements de la structure, pas des validations.';
$string['importdossierselfpos'] = 'Auto-positionnement du vaeiste : {$a->autopositionnement} ligne(s) restaurée(s), {$a->autopositionnementlaissees} laissée(s) telle(s) quelle(s) (une ligne déjà présente, une fiche ou un élément que ce site ne tient pas, ou un élément qui porte déjà autant de lignes qu\'il le peut). C\'est la parole du vaeiste, pas une validation.';
$string['importdossiersituations'] = 'Situations de travail : {$a->situations} élément(s) restauré(s) (situations entières, pièces, annotations, lignes d\'accord), {$a->situationslaissees} laissé(s) tel(s) quel(s) (une situation : emplacement déjà pris, identifiant déjà présent, fiche que ce site ne tient pas ou trop de versions ; une étiquette ou un lien vers une pièce que ce site ne tient pas, la situation revenant sans eux ; une pièce, une annotation ou un accord : identifiant déjà présent ou borne atteinte). Les annotations et les accords restaurés ne désignent aucun compte de ce site et n\'ouvrent aucune annotation ; rien n\'est une validation.';
$string['importdossierwithdrawnotice'] = 'Les attestations reprises d\'une archive ne sont rattachées à aucun compte de ce site. Seul l\'administrateur du site peut les retirer.';
$string['importencoding'] = 'Encodage du fichier';
$string['importencoding_help'] = 'L\'encodage des caractères du fichier déposé. UTF-8 est ce qu\'exportent la plupart des outils aujourd\'hui ; un tableur sous Windows écrit souvent du Windows-1252. Se tromper n\'arrête pas l\'import : cela retire silencieusement les accents de tous les intitulés. Si les intitulés arrivent abîmés, retirez le référentiel de la fiche dans Administration du site, Compétences, Référentiels de compétences (possible tant qu\'aucun vaeiste n\'a déclaré), puis réimportez-la avec l\'autre encodage.';
$string['importfichecode'] = 'Code de la fiche';
