$string['privacy:metadata:consent:manageruuid'] = 'L\'identifiant opaque du responsable d\'une ligne restaurée d\'une archive ; vide pour une ligne écrite ici. La ligne est supprimée quand cette personne est effacée.';
$string['privacy:metadata:consent:state'] = 'Si l\'accord est donné ou retiré par cette ligne.';
